package com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.usecases;
import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.gateways.*; import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.models.*; import com.nm.fragmentsclean.sharedKernel.businesslogic.models.DateTimeProvider; import jakarta.transaction.Transactional; import org.springframework.stereotype.Component; import java.time.Duration; import java.util.*;
@Component public class CompleteEditorialSignalAnalysis { private final TopicCandidateRepository candidates;private final GenerationExecutionRepository executions;private final EditorialSignalAnalysisRepository signals;private final DateTimeProvider clock; public CompleteEditorialSignalAnalysis(TopicCandidateRepository c,GenerationExecutionRepository e,EditorialSignalAnalysisRepository s,DateTimeProvider clock){candidates=c;executions=e;signals=s;this.clock=clock;} @Transactional public void execute(List<SourceSignal> source,EditorialAnalysisPort.AnalysisResult result,Duration duration){var now=clock.now();for(var p:result.topics())candidates.save(TopicCandidate.detect(UUID.randomUUID(),p.subject(),p.suggestedAngle(),p.signalIds(),now));executions.save(new GenerationExecution(UUID.randomUUID(),"EDITORIAL_SIGNAL_ANALYSIS",result.model(),result.inputTokens(),result.outputTokens(),result.estimatedCost(),duration,"SUCCEEDED",now));signals.markAnalyzed(source.stream().map(SourceSignal::id).toList());} }
